# phs/baiying/comment_rules.py
from __future__ import annotations

import json
import os
import re
import uuid
from copy import deepcopy
from datetime import datetime, timezone
from difflib import SequenceMatcher
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class RuleCreate(BaseModel):
    category: str = Field(..., description="block_word/replace_word/intent_route/auto_reply")
    name: str = ""
    pattern: str = Field(..., min_length=1)
    mode: str = Field(default="fuzzy", description="regex/exact/fuzzy")
    enabled: bool = True
    priority: int = 0
    intent: Optional[str] = None
    action: str = "manual_flag"
    response: Optional[str] = None
    replacement: Optional[str] = None
    tags: List[str] = Field(default_factory=list)
    meta: Dict[str, Any] = Field(default_factory=dict)


class RuleUpdate(BaseModel):
    category: Optional[str] = None
    name: Optional[str] = None
    pattern: Optional[str] = None
    mode: Optional[str] = None
    enabled: Optional[bool] = None
    priority: Optional[int] = None
    intent: Optional[str] = None
    action: Optional[str] = None
    response: Optional[str] = None
    replacement: Optional[str] = None
    tags: Optional[List[str]] = None
    meta: Optional[Dict[str, Any]] = None


class RuleTestRequest(BaseModel):
    text: str
    product_id: Optional[str] = None
    scene: str = "default"
    context: Dict[str, Any] = Field(default_factory=dict)


class RuleStore:
    valid_categories = {"block_word", "replace_word", "intent_route", "auto_reply"}
    valid_modes = {"regex", "exact", "fuzzy"}

    def __init__(self, path: Optional[str] = None):
        default_path = Path("data") / "comment_rules" / "rules.json"
        self.path = Path(path or os.getenv("PHS_COMMENT_RULES_DB", default_path))
        self.lock = RLock()
        self.data: Dict[str, Any] = {"rules": [], "tests": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("rules", [])
            self.data.setdefault("tests", [])
        except Exception:
            self.path.replace(self.path.with_suffix(".corrupt.json"))
            self.data = {"rules": [], "tests": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _find_index(self, rule_id: str) -> int:
        for i, item in enumerate(self.data["rules"]):
            if item.get("id") == rule_id:
                return i
        return -1

    def _normalize_rule(self, item: Dict[str, Any]) -> Dict[str, Any]:
        category = item.get("category")
        mode = item.get("mode", "fuzzy")
        if category not in self.valid_categories:
            raise ValueError(f"invalid category: {category}")
        if mode not in self.valid_modes:
            raise ValueError(f"invalid mode: {mode}")
        item["tags"] = sorted(set(item.get("tags", [])))
        return item

    def list(
        self,
        category: Optional[str] = None,
        enabled: Optional[bool] = None,
        q: Optional[str] = None,
    ) -> List[Dict[str, Any]]:
        with self.lock:
            items = deepcopy(self.data["rules"])
        if category:
            items = [x for x in items if x.get("category") == category]
        if enabled is not None:
            items = [x for x in items if bool(x.get("enabled", True)) is enabled]
        if q:
            ql = q.lower()
            items = [
                x for x in items
                if ql in (x.get("name", "") + x.get("pattern", "") + " ".join(x.get("tags", []))).lower()
            ]
        return sorted(items, key=lambda x: (-int(x.get("priority", 0)), x.get("updated_at", "")))

    def get(self, rule_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(rule_id)
            if idx < 0:
                raise KeyError(rule_id)
            return deepcopy(self.data["rules"][idx])

    def create(self, payload: RuleCreate) -> Dict[str, Any]:
        item = self._normalize_rule(_dump(payload))
        item["id"] = uuid.uuid4().hex
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["rules"].append(item)
            self._save()
            return deepcopy(item)

    def update(self, rule_id: str, payload: RuleUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.lock:
            idx = self._find_index(rule_id)
            if idx < 0:
                raise KeyError(rule_id)
            item = self.data["rules"][idx]
            item.update(patch)
            self._normalize_rule(item)
            item["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def delete(self, rule_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(rule_id)
            if idx < 0:
                raise KeyError(rule_id)
            item = self.data["rules"].pop(idx)
            self._save()
            return deepcopy(item)

    def record_test(self, text: str, result: Dict[str, Any]) -> None:
        with self.lock:
            self.data["tests"].append({"id": uuid.uuid4().hex, "text": text, "result": result, "created_at": _now()})
            self.data["tests"] = self.data["tests"][-500:]
            self._save()


class RuleEngine:
    def __init__(self, store: RuleStore):
        self.store = store

    @staticmethod
    def _norm(text: str) -> str:
        return re.sub(r"\s+", "", (text or "").lower())

    def _match(self, text: str, pattern: str, mode: str) -> bool:
        if not pattern:
            return False
        if mode == "regex":
            try:
                return re.search(pattern, text, re.IGNORECASE) is not None
            except re.error:
                return False
        nt, np = self._norm(text), self._norm(pattern)
        if mode == "exact":
            return nt == np or np in nt
        if np in nt:
            return True
        if len(np) <= 1:
            return False
        if SequenceMatcher(None, nt, np).ratio() >= 0.72:
            return True
        window = max(len(np), 2)
        for i in range(0, max(1, len(nt) - window + 1)):
            if SequenceMatcher(None, nt[i:i + window], np).ratio() >= 0.82:
                return True
        return False

    def _replace(self, text: str, rule: Dict[str, Any]) -> str:
        pattern = rule.get("pattern", "")
        repl = rule.get("replacement", "") or ""
        mode = rule.get("mode", "fuzzy")
        if mode == "regex":
            try:
                return re.sub(pattern, repl, text, flags=re.IGNORECASE)
            except re.error:
                return text
        if mode == "exact":
            return text.replace(pattern, repl)
        return re.sub(re.escape(pattern), repl, text, flags=re.IGNORECASE)

    def evaluate(
        self,
        text: str,
        product_id: Optional[str] = None,
        scene: str = "default",
        context: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        rules = self.store.list(enabled=True)
        result: Dict[str, Any] = {
            "original_text": text,
            "clean_text": text,
            "blocked": False,
            "manual_flag": False,
            "intent": None,
            "action": None,
            "response": None,
            "script_query": None,
            "matched_rules": [],
            "product_id": product_id,
            "scene": scene,
            "context": context or {},
        }

        for rule in rules:
            if rule.get("category") != "block_word":
                continue
            if self._match(result["clean_text"], rule.get("pattern", ""), rule.get("mode", "fuzzy")):
                result["blocked"] = True
                result["manual_flag"] = True
                result["action"] = "manual_flag"
                result["matched_rules"].append(self._rule_hit(rule, "block_word"))
                return result

        for rule in rules:
            if rule.get("category") != "replace_word":
                continue
            if self._match(result["clean_text"], rule.get("pattern", ""), rule.get("mode", "fuzzy")):
                before = result["clean_text"]
                result["clean_text"] = self._replace(before, rule)
                result["matched_rules"].append(self._rule_hit(rule, "replace_word", {"before": before, "after": result["clean_text"]}))

        for rule in rules:
            if rule.get("category") != "intent_route":
                continue
            if self._match(result["clean_text"], rule.get("pattern", ""), rule.get("mode", "fuzzy")):
                result["intent"] = rule.get("intent") or rule.get("name") or "generic"
                result["action"] = rule.get("action", "script_match")
                result["matched_rules"].append(self._rule_hit(rule, "intent_route"))
                break

        if not result["action"]:
            result["action"] = "script_match"

        for rule in rules:
            if rule.get("category") != "auto_reply":
                continue
            if self._match(result["clean_text"], rule.get("pattern", ""), rule.get("mode", "fuzzy")):
                result["action"] = "auto_reply"
                result["response"] = rule.get("response") or ""
                result["matched_rules"].append(self._rule_hit(rule, "auto_reply"))
                break

        if result["action"] == "manual_flag":
            result["manual_flag"] = True
        elif result["action"] == "script_match":
            result["script_query"] = {
                "scene": scene,
                "product_id": product_id,
                "intent": result["intent"] or "generic",
                "text": result["clean_text"],
            }
        elif result["action"] == "auto_reply" and not result["response"]:
            result["manual_flag"] = True

        return result

    @staticmethod
    def _rule_hit(rule: Dict[str, Any], stage: str, extra: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        item = {
            "id": rule.get("id"),
            "stage": stage,
            "category": rule.get("category"),
            "name": rule.get("name"),
            "pattern": rule.get("pattern"),
            "mode": rule.get("mode"),
            "priority": rule.get("priority", 0),
        }
        if extra:
            item.update(extra)
        return item


def create_comment_rules_router(store: Optional[RuleStore] = None, prefix: str = "") -> APIRouter:
    db = store or RuleStore()
    engine = RuleEngine(db)
    router = APIRouter(prefix=prefix, tags=["comment-rules"])

    @router.get("/rules")
    def list_rules(
        category: Optional[str] = None,
        enabled: Optional[bool] = Query(default=None),
        q: Optional[str] = None,
    ) -> Dict[str, Any]:
        items = db.list(category=category, enabled=enabled, q=q)
        return {"items": items, "count": len(items)}

    @router.post("/rules")
    def create_rule(payload: RuleCreate) -> Dict[str, Any]:
        try:
            return db.create(payload)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    @router.post("/rules/test")
    def test_rule(payload: RuleTestRequest) -> Dict[str, Any]:
        result = engine.evaluate(payload.text, product_id=payload.product_id, scene=payload.scene, context=payload.context)
        db.record_test(payload.text, result)
        return result

    @router.get("/rules/{rule_id}")
    def get_rule(rule_id: str) -> Dict[str, Any]:
        try:
            return db.get(rule_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="rule not found")

    @router.put("/rules/{rule_id}")
    def update_rule(rule_id: str, payload: RuleUpdate) -> Dict[str, Any]:
        try:
            return db.update(rule_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="rule not found")
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    @router.delete("/rules/{rule_id}")
    def delete_rule(rule_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": db.delete(rule_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="rule not found")

    return router


class CommentRulesProvider:
    provider_id = "comment_rules"
    name = "Comment Rules"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = RuleStore(self.config.get("db_path"))
        self.engine = RuleEngine(self.store)
        self.router = create_comment_rules_router(self.store)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "rule_count": len(self.store.data.get("rules", [])),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/rules", "/rules/test"],
            "categories": sorted(RuleStore.valid_categories),
            "modes": sorted(RuleStore.valid_modes),
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> CommentRulesProvider:
    return CommentRulesProvider(config)


